package glitch

import data.glitch_lib

# Helper to check if conditional is a switch-type (multi-branch)
is_switch_type(cond) {
    cond.type.name == "SWITCH"
}

# Helper to check if conditional has no fallback (lack of is_default on final else)
lacks_fallback(cond) {
    cond.else_statement == null
    not cond.is_default
}

# Helper to check if conditional has fallback but it's empty/no-op
has_empty_fallback(cond) {
    cond.is_default
    count(cond.statements) == 0
}

# Helper to check if there are nested conditionals without fallback at any level
nested_lacks_complete_fallback(cond) {
    is_switch_type(cond)
    cond.else_statement != null
    not cond.else_statement.is_default
    nested_branch := cond.else_statement
    lacks_fallback(nested_branch)
}

# Check if conditional variable comes from external/computed source
is_external_driven(cond) {
    walk(cond.condition, [_, n])
    n.ir_type == "FunctionCall"
} else {
    walk(cond.condition, [_, n])
    n.ir_type == "VariableReference"
}

# Check if conditional involves resource selection or configuration fields
is_resource_selection_context(cond) {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

    walk(au, [_, node])
    node == cond

    # Check for resource configuration attributes
    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    selection_fields := {"instance_type", "vm_size", "machine_type", "sku", "tier", "region", "zone", "encryption_type", "protocol_version", "auth_method", "address_family", "schema_version"}
    contains(lower(attr.name), selection_fields[_])
}

# Main detection: multi-branch conditional without comprehensive fallback
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    conditions := glitch_lib.all_conditional_statements(parent)
    cond := conditions[_]

    # Must be a switch-type (multi-branch discrete evaluation)
    is_switch_type(cond)

    # At least 2 branches (multi-branch)
    count({c | c := conditions[_]; c != cond; c.condition == cond.condition}) > 0

    # Lacks proper fallback mechanism
    any([
        lacks_fallback(cond),
        has_empty_fallback(cond),
        nested_lacks_complete_fallback(cond)
    ])

    # Input-driven control flow
    is_external_driven(cond)

    result := {
        "type": "sec_no_default_switch",
        "element": cond,
        "path": parent.path,
        "description": "Missing Default Case in Switch Statement - Multi-branch conditional lacks comprehensive fallback mechanism for unhandled values. (CWE-478)"
    }
}

# Detection through hash/map lookup without default
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    au := atomic_units[_]

    attrs := glitch_lib.all_attributes(au)
    attr := attrs[_]

    # Check for hash/map used as lookup table
    attr.value.ir_type == "Hash"

    # Hash has entries but no default/catch-all key
    hash_entries := {k | k := attr.value.value[_]}
    count(hash_entries) > 1

    # Check for missing default patterns
    default_patterns := {"default", "else", "other", "*", "_", "null", "undefined"}
    not any_default_key(attr.value.value, default_patterns)

    # Used for resource configuration selection
    selection_context(attr.name)

    result := {
        "type": "sec_no_default_switch",
        "element": attr,
        "path": parent.path,
        "description": "Missing Default Case in Switch Statement - Lookup table lacks comprehensive fallback for unhandled keys. (CWE-478)"
    }
